-- PERFORM-001: feedback and releases are append-only, with explicit recipient custody.
CREATE TABLE wl_review_cycles(id TEXT PRIMARY KEY,name TEXT NOT NULL,due_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',questions TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE wl_review_subjects(cycle_id TEXT NOT NULL REFERENCES wl_review_cycles(id),person_id TEXT NOT NULL REFERENCES wl_people(id),PRIMARY KEY(cycle_id,person_id));
CREATE TABLE wl_review_assignments(id TEXT PRIMARY KEY,cycle_id TEXT NOT NULL,person_id TEXT NOT NULL,member_id TEXT NOT NULL REFERENCES wl_members(id),role TEXT NOT NULL CHECK(role IN ('self','peer','manager')),due_date TEXT NOT NULL,UNIQUE(cycle_id,person_id,member_id,role),FOREIGN KEY(cycle_id,person_id) REFERENCES wl_review_subjects(cycle_id,person_id));
CREATE TABLE wl_review_inputs(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT UNIQUE NOT NULL,assignment_id TEXT NOT NULL REFERENCES wl_review_assignments(id),author TEXT NOT NULL,answers TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE wl_review_notes(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT UNIQUE NOT NULL,cycle_id TEXT NOT NULL,person_id TEXT NOT NULL,author TEXT NOT NULL,note TEXT NOT NULL,rating TEXT NOT NULL,created_at INTEGER NOT NULL,FOREIGN KEY(cycle_id,person_id) REFERENCES wl_review_subjects(cycle_id,person_id));
CREATE TABLE wl_review_summaries(id TEXT PRIMARY KEY,cycle_id TEXT NOT NULL,person_id TEXT NOT NULL,version INTEGER NOT NULL,summary TEXT NOT NULL,rating TEXT NOT NULL,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(cycle_id,person_id,version),FOREIGN KEY(cycle_id,person_id) REFERENCES wl_review_subjects(cycle_id,person_id));
CREATE TABLE wl_review_recipients(summary_id TEXT NOT NULL REFERENCES wl_review_summaries(id),member_id TEXT NOT NULL REFERENCES wl_members(id),kind TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(summary_id,member_id));
CREATE TABLE wl_review_withholdings(summary_id TEXT NOT NULL REFERENCES wl_review_summaries(id),manager TEXT NOT NULL REFERENCES wl_members(id),reason TEXT NOT NULL,author TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(summary_id,manager));
CREATE TABLE wl_review_acknowledgments(summary_id TEXT NOT NULL REFERENCES wl_review_summaries(id),member_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(summary_id,member_id));
CREATE TABLE wl_review_appeals(id TEXT PRIMARY KEY,summary_id TEXT NOT NULL REFERENCES wl_review_summaries(id),member_id TEXT NOT NULL,reason TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TRIGGER wl_review_inputs_update BEFORE UPDATE ON wl_review_inputs BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_inputs_delete BEFORE DELETE ON wl_review_inputs BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_notes_update BEFORE UPDATE ON wl_review_notes BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_notes_delete BEFORE DELETE ON wl_review_notes BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_summaries_update BEFORE UPDATE ON wl_review_summaries BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_summaries_delete BEFORE DELETE ON wl_review_summaries BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_recipients_update BEFORE UPDATE ON wl_review_recipients BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_recipients_delete BEFORE DELETE ON wl_review_recipients BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_withholdings_update BEFORE UPDATE ON wl_review_withholdings BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_withholdings_delete BEFORE DELETE ON wl_review_withholdings BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_acknowledgments_update BEFORE UPDATE ON wl_review_acknowledgments BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_acknowledgments_delete BEFORE DELETE ON wl_review_acknowledgments BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_appeals_update BEFORE UPDATE ON wl_review_appeals BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_appeals_delete BEFORE DELETE ON wl_review_appeals BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_cycle_config BEFORE UPDATE OF name,due_date,questions ON wl_review_cycles BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_cycle_delete BEFORE DELETE ON wl_review_cycles BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_assignments_update BEFORE UPDATE ON wl_review_assignments BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_assignments_delete BEFORE DELETE ON wl_review_assignments BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_subjects_update BEFORE UPDATE ON wl_review_subjects BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
CREATE TRIGGER wl_review_subjects_delete BEFORE DELETE ON wl_review_subjects BEGIN SELECT RAISE(ABORT,'willow_immutable'); END;
